describe("renderWeekTable location", () => {
  it("prefixes the location with @", () => {
    const html = renderWeekTable([{ id: "p1", name: "Ada", role: "barista" }], [{ id: "s1", personId: "p1", start: "2026-03-04T09:00:00Z", end: "2026-03-04T17:00:00Z", location: "Bar" }], WEEK);
    expect(html).toContain("@ Bar");
  });
});

